SourceCode.Declaration:
/// <summary>
/// MET_86267_CustomerStatementReport developed by ydavapa on 16th Oct 2023.
/// Created extension class to create/update activity email while updating/creating statment email. 
/// </summary>
[ExtensionOf(tableStr(LogisticsElectronicAddress))]
final class LogisticsElectronicAddress_Metcash_Extension
{
    #Define.LocationRoleName('Customer Transaction')
}

Method.Source:
    public void update()
    {
        LogisticsElectronicAddress logisticsElectronicAddressForActivityContact;
        LogisticsLocationRole      locationRole;
        DirPartyLocation           dirPartyLocation;
        CustTable                  custTable, custTableUpdate;
        CustParameters             custParameters;
        Map                        locationRoleMap;
        container                  locationRoleCon;

        next update();
       
        custParameters = CustParameters::find();

        if(custParameters.METIsD365CustomerStatement)
        {
            select firstonly RecId, MET_IsActivitySync from custTable join dirPartyLocation where
                        dirPartyLocation.Party == custTable.Party && dirPartyLocation.Location == this.Location
                        && dirPartyLocation.IsLocationOwner && dirPartyLocation.IsPostalAddress == 0;

            LogisticsElectronicAddress logisticsElectronicAddressForStatement =
                    MET_CreateCustomerContactActivityReportService::getLogisticsElectronicAddress(this.Location, LogisticsLocationRoleType::Statement);
            if(this.Type == LogisticsElectronicAddressMethodType::Email && logisticsElectronicAddressForStatement.RecId && this.Locator && !custTable.MET_IsActivitySync)
            {
                locationRoleMap = new Map(Types::Int64, Types::String);
                locationRole = LogisticsLocationRole::findByName(#LocationRoleName);
                if (locationRole)
                {
                    locationRoleMap.insert(locationRole.RecId, locationRole.description());
                    locationRoleCon = map2Con(locationRoleMap);
                }

                logisticsElectronicAddressForActivityContact.Type        = LogisticsElectronicAddressMethodType::Email;
                logisticsElectronicAddressForActivityContact.Locator     = this.Locator;
                logisticsElectronicAddressForActivityContact.Location    = this.Location;
                logisticsElectronicAddressForActivityContact.Description = "@MET:ActivityEmail";
                logisticsElectronicAddressForActivityContact.IsPrimary   = NoYes::No;

                LogisticsElectronicAddress logisticsElectronicAddressForActivity =
                        MET_CreateCustomerContactActivityReportService::getLogisticsElectronicAddress(this.Location, LogisticsLocationRoleType::None);
                if(logisticsElectronicAddressForActivity.RecId == 0)
                {
                    ttsBegin;
                    logisticsElectronicAddressForActivityContact.insert();
                    LogisticsEntityLocationRoleMap::createEntityLocationRoles(tableNum(LogisticsElectronicAddressRole), logisticsElectronicAddressForActivityContact.RecId, conPeek(locationRoleCon, 1), true);
                
                    select firstonly forupdate custTableUpdate
                        where custTableUpdate.RecId == custTable.RecId;
                    if(custTableUpdate.RecId)
                    {
                        custTableUpdate.MET_IsActivitySync = true;
                        custTableUpdate.update();
                    }
                    ttsCommit;
                    info(strFmt("@MET:ActityEmailCreationMessage", this.Locator, logisticsElectronicAddressForActivityContact.recid));
                }
            }
        }
    }
